  id: string;
  category_id: string;
  name: string;
  price: number;
  is_available: boolean;
  created_at: string;
  category?: MenuCategory;
}

export type TableStatus = 'free' | 'occupied';

export interface CafeTable {
  id: string;
  label: string;
  seats: number;
